.xt-layout-sider {
  background-color: #cfe6f9;
  border-radius: 5px
}

::v-deep .el-tree {
  background: transparent;
  color: #46506d;
}

::v-deep .el-tree--highlight-current .el-tree-node.is-current > .el-tree-node__content {
  background: none
}

::v-deep .el-tree-node__content:hover {
  background: none
}

.e_earc {
