.table_detial {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 10px;

  .table_info {
    display: flex;

    .info_item {
      display: flex;
      align-items: center;
      font-size: 14px;
      padding: 0px 12px 0px 12px;
      margin-right: 30px;

      &:last-child {
        margin-right: 0;
      }

      img {
        margin-right: 7px
      }

      span {
        display: inline-block;
        line-height: 40px;
        color: #46506d;
        cursor: pointer;
      }

      i {
        font-style: normal;
        color: #409EFF;
        font-weight: 900;
        margin-left: 5px;

      }

    }
  }
}

